int kvm_update_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps) {
    int i;

    if (!kvm || !ps) {
        return 0;
    }

    mutex_lock(&kvm->pit_state_mutex);

    kvm->pit_state->hpet = ps->hpet;

    for (i = 0; i < KVM_PIT_NUM_CHANNELS; i++) {
        kvm->pit_state->channels[i].count = ps->channels[i].count;
        kvm->pit_state->channels[i].latch = ps->channels[i].latch;
        kvm->pit_state->channels[i].mode = ps->channels[i].mode;
        kvm->pit_state->channels[i].flags = ps->channels[i].flags;
    }

    kvm->pit_state->flags = ps->flags;

    mutex_unlock(&kvm->pit_state_mutex);

    return 0;
}
